code.java:
class Solution {
    public int triangularSum(int[] nums){
        for(int length=nums.length;length>1;length--)for(int i=0;i+1<length;i++)nums[i]=(nums[i]+nums[i+1])%10;
        return nums[0];
    }
}

code.kotlin:
class Solution {
    fun triangularSum(nums:IntArray):Int{
        for(length in nums.size downTo 2)for(i in 0 until length-1)nums[i]=(nums[i]+nums[i+1])%10;
        return nums[0]
    }
}

